  'holdall': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.holdall\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Hold-All Domination\ndescription: Teams capture boxes as in Domination, but a team scores only while it holds every box at once.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while one team holds every box" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\n  min_zones:       { type: int, min: 1, max: 64,    default: 2,    label: "Boxes in play before anyone can score" }\ni18n:\n  pt:\n    name: Domínio Total\n    description: As equipas capturam caixas como no Domínio, mas uma equipa só pontua enquanto tiver todas as caixas ao mesmo tempo.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por ponto enquanto uma equipa tem todas as caixas\n      points_per_tick: Pontos por intervalo\n      min_zones: Caixas em jogo antes de alguém poder pontuar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on each box: a team captures the box by holding its\n-- input, as in Domination. The box does not score by itself: the field\n-- controller\'s field.lua scores a team only while it holds every box.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on the field controller: while one team holds every\n-- zone box (and at least params.min_zones of them are in play), it scores\n-- params.points_per_tick every params.tick_s seconds. Box owners come from\n-- the boxes\' STATE reports, which can arrive a little after the capture\n-- event, so the check also runs every second.\n\nlocal fs = state.field { holder = nil }\nlocal tick\n\nlocal function zone_ids()\n  local ids = {}\n  for _, n in ipairs(field.nodes("zone")) do\n    ids[#ids + 1] = n.id\n  end\n  return ids\nend\n\nlocal function check()\n  local ids = zone_ids()\n  local team = nil\n  if #ids >= params.min_zones then\n    team = field.common_owner(ids)\n  end\n  if team == fs.holder then\n    return\n  end\n  if fs.holder ~= nil then\n    cancel(tick)\n    tick = nil\n    emit("holdall.scoring_stop", { team = fs.holder })\n  end\n  fs.holder = team\n  if team ~= nil then\n    emit("holdall.scoring_start", { team = team })\n    -- The first points come one full tick after the last box fell.\n    tick = every(params.tick_s, function()\n      score.add(team, params.points_per_tick, "holdall")\n    end)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'kill_confirmed': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.kill_confirmed\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Kill Confirmed\ndescription: >-\n  Players carry signed NFC tags. A team presses its button at the station and scans the tags it\n  collected: an enemy\'s tag confirms the kill (points for the team, a penalty for the tag\'s team), a\n  teammate\'s tag denies it. Forged tags and tags from another game are refused.\nroles:\n  station: { requires: [nfc, team_input], optional: [display] }\nparams:\n  confirm_points: { type: int, min: 0, max: 100, default: 1, label: "Points for a confirmed kill" }\n  penalty_points: { type: int, min: 0, max: 100, default: 1, label: "Points the killed player\'s team loses" }\n  turn_in_s:      { type: int, min: 3, max: 120, default: 20, label: "Seconds to scan tags after pressing the team button" }\n  retag_after_s:  { type: int, min: 1, max: 3600, default: 60, label: "Seconds before the same player\'s tag counts again" }\ni18n:\n  pt:\n    name: Baixa Confirmada\n    description: >-\n      Cada participante leva uma etiqueta NFC assinada. Uma equipa carrega no seu botão na estação e lê as\n      etiquetas que recolheu: a etiqueta de alguém da equipa adversária confirma a baixa (pontos para a\n      equipa e penalização para a equipa da etiqueta); a de alguém da própria equipa nega-a. Etiquetas\n      falsificadas ou de outro jogo são recusadas.\n    params:\n      confirm_points: Pontos por baixa confirmada\n      penalty_points: Pontos que perde a equipa de quem foi abatido\n      turn_in_s: Segundos para ler etiquetas depois de carregar no botão da equipa\n      retag_after_s: Segundos até a etiqueta da mesma pessoa voltar a contar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Kill Confirmed: players carry signed NFC tags (protocol/nfc-tag.md). A team\n-- presses its button at the station, then scans the tags it collected within\n-- turn_in_s seconds (each scan keeps the station open). An enemy\'s tag\n-- confirms the kill: confirm_points for the team, penalty_points off the\n-- tag\'s team. A teammate\'s tag denies the kill: no points. The same player\'s\n-- tag counts again only after retag_after_s. Forged tags, tags from another\n-- game and tags without a team are refused; the shell checks the signature\n-- with the game key and says why in nfc.tag\'s reason.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal open_team -- the team turning in tags\nlocal closes_at = 0\nlocal closer\nlocal counted = {} -- player -> game time when their tag last counted\nlocal message, failed, fade\n\nlocal function show()\n  local data = { message = message, error = failed }\n  if open_team then\n    data.team = open_team\n    data.left = math.max(0, math.ceil(closes_at - game.time()))\n  end\n  ui.screen("tags", data)\nend\n\n-- A message under the station\'s state, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n    fade = nil\n  end\n  if text then\n    fade = after(4, function()\n      fade = nil\n      message, failed = nil, false\n      show()\n    end)\n  end\nend\n\nlocal function close()\n  open_team, closer = nil, nil\n  say(nil, false)\nend\n\nlocal function open(team)\n  open_team = team\n  closes_at = game.time() + params.turn_in_s\n  if closer then\n    cancel(closer)\n  end\n  closer = after(params.turn_in_s, close)\nend\n\non("game.start", show)\n\non("team_input.press", function(e)\n  open(e.team)\n  say("Scan your tags", false)\nend)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("kill confirmed: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if open_team == nil then\n    return say("Press your team\'s button first", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local last = counted[e.player]\n  if last and game.time() - last < params.retag_after_s then\n    return say("Tag already counted", true)\n  end\n  counted[e.player] = game.time()\n  open(open_team)\n  if e.team == open_team then\n    emit("kill.denied", { team = open_team, player = e.player, owner = e.team })\n    say("Kill denied: " .. e.player, false)\n  else\n    emit("kill.confirmed", { team = open_team, player = e.player, owner = e.team })\n    score.add(open_team, params.confirm_points, "kill")\n    score.add(e.team, -params.penalty_points, "killed")\n    say("Kill confirmed: " .. e.player, false)\n  end\nend)\n\n-- The time left to scan, once a second while the station is open.\nevery(1, function()\n  if open_team then\n    show()\n  end\nend)\n',
    'assets/screens/tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The Kill Confirmed station. Data: team (the team turning in tags, while the\n# station is open), left (seconds left to scan), message, error.\ntemplate: tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: KILL CONFIRMED\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{!team}" }\n      - type: label\n        text: "{team|upper}: SCAN TAGS"\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Press your button\n    style: { font_size: 28, visible: "{!team}" }\n  - type: label\n    text: then scan the tags\n    style: { font_size: 20, color: muted, visible: "{!team}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: progress_bar\n    value: "{left / params.turn_in_s}"\n    style: { width: 240, height: 8, color: team, visible: "{team}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Enemy tag: confirmed. Team tag: denied."\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'laststand': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.laststand\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Last Stand\ndescription: The defenders start with every zone. Once they are down to their last zone, a countdown to defeat runs until they retake another one.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  attackers:       { type: team, default: red, label: "Attackers (win when the defenders fall)" }\n  defenders:       { type: team, default: blue, label: "Defenders (start with every zone)" }\n  countdown_s:     { type: int, min: 10, max: 3600, default: 120, label: "Countdown to defeat (s)" }\n  last_zones:      { type: int, min: 0, max: 63, default: 1, label: "The countdown runs while the defenders hold this many zones or fewer" }\n  min_zones:       { type: int, min: 1, max: 64, default: 2, label: "Zones in play before the countdown can run" }\n  reset:           { type: bool, default: true, label: "The countdown starts over after a retake (otherwise it carries on where it stopped)" }\n  end_game:        { type: bool, default: true, label: "End the game when the defenders fall" }\ni18n:\n  pt:\n    name: Último Elemento\n    description: Os defensores começam com todas as zonas. Quando ficam reduzidos à última zona, corre uma contagem para a derrota até reconquistarem outra.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      attackers: Atacantes (ganham quando os defensores caem)\n      defenders: Defensores (começam com todas as zonas)\n      countdown_s: Contagem para a derrota (s)\n      last_zones: A contagem corre enquanto os defensores tiverem este número de zonas ou menos\n      min_zones: Zonas em jogo antes de a contagem poder correr\n      reset: A contagem recomeça do início após uma reconquista (senão continua de onde parou)\n      end_game: Terminar o jogo quando os defensores caem\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on each zone box: the defenders hold the box when the game\n-- starts; any team captures it by holding its input. The field controller\'s\n-- field.lua counts the defenders\' zones and runs the countdown to defeat.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("game.start", function()\n  if s.owner == nil then\n    capture(params.defenders)\n  end\nend)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on the field controller. Once the defence is set up (the\n-- defenders have held more than params.last_zones zones, or 30 s have\n-- passed: box owners come from STATE reports, which can lag), a countdown of\n-- params.countdown_s seconds runs whenever they hold params.last_zones\n-- zones or fewer. Retaking a zone stops it; it starts over (params.reset)\n-- or carries on where it stopped. When it runs out the defenders are\n-- defeated, and with params.end_game the attackers win the game.\n\nlocal fs = state.field { held = 0, countdown = false, defeated = false }\nlocal ready = false -- the defence is set up\nlocal timer -- the defeat timer, while the countdown runs\nlocal left = params.countdown_s -- seconds the next countdown starts from\nlocal deadline = 0\n\nlocal function defeat()\n  timer = nil\n  fs.countdown = false\n  fs.defeated = true\n  emit("laststand.defeated", { team = params.defenders })\n  if params.end_game then\n    game.win(params.attackers)\n  end\nend\n\nlocal function check()\n  if fs.defeated then\n    return\n  end\n  local zones = field.nodes("zone")\n  local held = 0\n  for _, n in ipairs(zones) do\n    if field.owner(n.id) == params.defenders then\n      held = held + 1\n    end\n  end\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if held > params.last_zones or game.time() >= 30 then\n    ready = true\n  end\n  local danger = ready and #zones >= params.min_zones and held <= params.last_zones\n  if danger and timer == nil then\n    deadline = game.time() + left\n    timer = after(left, defeat)\n    fs.countdown = true\n    emit("laststand.countdown_start", { team = params.defenders, duration_s = math.ceil(left) })\n  elseif not danger and timer ~= nil then\n    cancel(timer)\n    timer = nil\n    fs.countdown = false\n    local remaining = deadline - game.time()\n    emit(\n      "laststand.countdown_cancel",\n      { team = params.defenders, duration_s = math.ceil(remaining) }\n    )\n    left = params.reset and params.countdown_s or math.max(remaining, 0.1)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'player_checkin': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.player_checkin\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Player Check-in\ndescription: >-\n  Players check in at a checkpoint by scanning their signed NFC tag. The box counts the players of each\n  team and gives their team points for each check-in. A player counts once, or again after a set time.\n  Forged tags and tags from another game are refused.\nroles:\n  checkpoint: { requires: [nfc], optional: [display] }\nparams:\n  points:         { type: int, min: 0, max: 1000, default: 1, label: "Points for the player\'s team per check-in" }\n  repeat_after_s: { type: int, min: 0, max: 86400, default: 0, label: "Seconds before the same player counts again (0: once per game)" }\ni18n:\n  pt:\n    name: Registo de Presença\n    description: >-\n      Cada participante faz o registo num ponto de controlo lendo a sua etiqueta NFC assinada. A caixa conta\n      as pessoas de cada equipa e dá pontos à equipa por cada registo. Cada pessoa conta uma vez, ou de\n      novo ao fim de um tempo definido. Etiquetas falsificadas ou de outro jogo são recusadas.\n    params:\n      points: Pontos para a equipa por cada registo\n      repeat_after_s: "Segundos até a mesma pessoa voltar a contar (0: uma vez por jogo)"\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Player Check-in: players check in at a checkpoint with their signed NFC\n-- tag (protocol/nfc-tag.md). The box counts check-ins per team and gives the\n-- player\'s team `points` for each. A player counts once per game, or again\n-- after repeat_after_s seconds; a scan before that is a duplicate and is\n-- refused. Forged tags, tags from another game and tags without a team are\n-- refused (the shell checks the signature and says why in nfc.tag\'s reason).\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal seen = {} -- player -> game time of their last check-in that counted\nlocal count = {} -- team -> check-ins\nlocal order = {} -- teams in the order they first checked in\nlocal total = 0\nlocal last_team\nlocal message, failed, fade\n\nlocal function counts()\n  local parts = {}\n  for _, team in ipairs(order) do\n    parts[#parts + 1] = string.upper(team) .. " " .. count[team]\n  end\n  return table.concat(parts, "  ")\nend\n\nlocal function show()\n  ui.screen("checkin", {\n    total = total,\n    counts = counts(),\n    team = last_team,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the counts, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("check-in: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local t = seen[e.player]\n  if t and (params.repeat_after_s == 0 or game.time() - t < params.repeat_after_s) then\n    return say("Already checked in", true)\n  end\n  seen[e.player] = game.time()\n  if count[e.team] == nil then\n    count[e.team] = 0\n    order[#order + 1] = e.team\n  end\n  count[e.team] = count[e.team] + 1\n  total = total + 1\n  last_team = e.team\n  emit("player.checkin", { team = e.team, player = e.player })\n  score.add(e.team, params.points, "checkin")\n  say("Checked in: " .. e.player, false)\nend)\n',
    'assets/screens/checkin.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The checkpoint. Data: total (check-ins), counts (per team, as text),\n# team (of the last check-in), message, error.\ntemplate: checkin\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: CHECK-IN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{total}"\n    style: { font_size: 48 }\n  - type: label\n    text: players checked in\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{counts}"\n    style: { font_size: 20, visible: "{counts}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to check in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'respawn': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.respawn\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Respawn and Lives\ndescription: >-\n  A respawn point counts lives. Players scan their signed NFC tag (or press their team\'s button) to come\n  back into the game; each respawn takes a life from their team, or from the player with per-player\n  lives, and a player must wait a cooldown between respawns. When a team has no lives left, the next\n  respawn is refused and the team is eliminated.\nroles:\n  respawn: { requires: [nfc], optional: [team_input, display] }\nparams:\n  lives:              { type: int, min: 1, max: 1000, default: 20, label: "Lives: respawns per team, or per player with per-player lives" }\n  per_player:         { type: bool, default: false, label: "Count lives per player (needs NFC tags) instead of per team" }\n  respawn_cooldown_s: { type: int, min: 0, max: 600, default: 30, label: "Seconds a player waits between respawns" }\ni18n:\n  pt:\n    name: Reentradas e Vidas\n    description: >-\n      Um ponto de reentrada conta as vidas. Cada participante lê a sua etiqueta NFC assinada (ou carrega no\n      botão da sua equipa) para voltar ao jogo; cada reentrada gasta uma vida da equipa, ou da própria\n      pessoa com vidas individuais, e há um tempo de espera entre reentradas. Quando uma equipa fica sem\n      vidas, a reentrada seguinte é recusada e a equipa é eliminada.\n    params:\n      lives: "Vidas: reentradas por equipa, ou por pessoa com vidas individuais"\n      per_player: Contar as vidas por pessoa (precisa de etiquetas NFC) em vez de por equipa\n      respawn_cooldown_s: Segundos de espera entre reentradas de cada pessoa\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Respawn and Lives: a respawn point counts lives. A player scans their\n-- signed NFC tag (protocol/nfc-tag.md), or presses their team\'s button, to\n-- come back into the game. Each respawn takes one of the team\'s `lives`, or\n-- one of the player\'s own with per_player. A player waits respawn_cooldown_s\n-- between respawns; button presses carry no player, so they only have a 2 s\n-- guard against double presses. When a team has no lives left, the next\n-- respawn is refused and team.eliminated is sent (once). Lives are counted on\n-- this box: give each team one respawn point, or share one.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\nlocal BUTTON_GUARD_S = 2\n\nlocal lives = {} -- team, or player with per_player -> lives left\nlocal last = {} -- player id, or "team:<team>" for buttons -> game time of the last respawn\nlocal out = {} -- team -> true once team.eliminated was sent\nlocal message, failed, fade\nlocal shown = { lives = params.lives }\n\nlocal function show()\n  ui.screen("respawn", {\n    team = shown.team,\n    player = shown.player,\n    lives = shown.lives,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the lives count, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\nlocal function lives_of(key)\n  if lives[key] == nil then\n    lives[key] = params.lives\n  end\n  return lives[key]\nend\n\nlocal function respawn(team, player)\n  if params.per_player and player == nil then\n    return say("Scan your tag", true)\n  end\n  if team == nil and not params.per_player then\n    return say("This tag has no team", true)\n  end\n  local who = player or ("team:" .. team)\n  local wait_s = player and params.respawn_cooldown_s or BUTTON_GUARD_S\n  local t = last[who]\n  if t and game.time() - t < wait_s then\n    return say("Wait " .. math.ceil(wait_s - (game.time() - t)) .. " s", true)\n  end\n  local key = params.per_player and player or team\n  shown.team, shown.player = team, player\n  shown.lives = lives_of(key)\n  if lives_of(key) <= 0 then\n    if not params.per_player and not out[team] then\n      out[team] = true\n      emit("team.eliminated", { team = team })\n    end\n    return say(params.per_player and "No lives left" or "No lives left: team out", true)\n  end\n  lives[key] = lives[key] - 1\n  last[who] = game.time()\n  shown.lives = lives[key]\n  emit("player.respawn", { team = team, player = player, lives_left = lives[key] })\n  say("Back in the game", false)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("respawn: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  respawn(e.team, e.player)\nend)\n\non("team_input.press", function(e)\n  respawn(e.team, nil)\nend)\n',
    'assets/screens/respawn.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The respawn point. Data: lives (left, for the last team or player),\n# team, player (the last respawn), message, error.\ntemplate: respawn\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: RESPAWN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lives}"\n    style: { font_size: 48, color: "{lives == 0 && \'danger\' || \'white\'}" }\n  - type: label\n    text: lives left\n    style: { font_size: 20, color: muted, visible: "{!team && !player}" }\n  - type: label\n    text: "lives left for {team|upper}"\n    style: { font_size: 20, color: team, visible: "{team && !params.per_player}" }\n  - type: label\n    text: "lives left for {player}"\n    style: { font_size: 20, color: muted, visible: "{player && params.per_player}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to come back in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
};
